from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class Requirement:
    id: str
    text: str
    kind: str
    value: object | None = None
    group: str = ""


def req(n: int, text: str, kind: str, value=None, group: str = "") -> Requirement:
    return Requirement(f"R{n:03d}", text, kind, value, group)


